SELECT setval('usuarios_id_seq', GREATEST((SELECT COALESCE(MAX(id), 0) FROM usuarios), 1), EXISTS (SELECT 1 FROM usuarios));
SELECT setval('clientes_id_cliente_seq', GREATEST((SELECT COALESCE(MAX(id_cliente), 0) FROM clientes), 1), EXISTS (SELECT 1 FROM clientes));
SELECT setval('productos_id_producto_seq', GREATEST((SELECT COALESCE(MAX(id_producto), 0) FROM productos), 1), EXISTS (SELECT 1 FROM productos));
SELECT setval('ventas_id_venta_seq', GREATEST((SELECT COALESCE(MAX(id_venta), 0) FROM ventas), 1), EXISTS (SELECT 1 FROM ventas));
SELECT setval('detalle_ventas_id_detalle_seq', GREATEST((SELECT COALESCE(MAX(id_detalle), 0) FROM detalle_ventas), 1), EXISTS (SELECT 1 FROM detalle_ventas));
SELECT setval('pedidos_id_pedido_seq', GREATEST((SELECT COALESCE(MAX(id_pedido), 0) FROM pedidos), 1), EXISTS (SELECT 1 FROM pedidos));
SELECT setval('detalle_pedidos_id_detalle_seq', GREATEST((SELECT COALESCE(MAX(id_detalle_pedido), 0) FROM detalle_pedidos), 1), EXISTS (SELECT 1 FROM detalle_pedidos));
SELECT setval('desechos_id_desecho_seq', GREATEST((SELECT COALESCE(MAX(id_desecho), 0) FROM desechos), 1), EXISTS (SELECT 1 FROM desechos));

ALTER TABLE productos DROP CONSTRAINT IF EXISTS productos_valores_validos;
ALTER TABLE productos ADD CONSTRAINT productos_valores_validos CHECK (cantidad >= 0 AND stock_minimo >= 0 AND precio_compra >= 0 AND precio_venta >= 0 AND estado IN ('Activo', 'Inactivo'));
ALTER TABLE clientes DROP CONSTRAINT IF EXISTS clientes_estado_valido;
ALTER TABLE clientes ADD CONSTRAINT clientes_estado_valido CHECK (estado IN ('Activo', 'Inactivo'));
ALTER TABLE ventas DROP CONSTRAINT IF EXISTS ventas_valores_validos;
ALTER TABLE ventas ADD CONSTRAINT ventas_valores_validos CHECK (total >= 0 AND metodo_pago IN ('Efectivo', 'SINPE Móvil', 'Tarjeta', 'Transferencia') AND estado IN ('Completada', 'Cancelada'));
ALTER TABLE detalle_ventas DROP CONSTRAINT IF EXISTS detalle_ventas_valores_validos;
ALTER TABLE detalle_ventas ADD CONSTRAINT detalle_ventas_valores_validos CHECK (cantidad > 0 AND precio_unitario >= 0 AND subtotal >= 0);
ALTER TABLE pedidos DROP CONSTRAINT IF EXISTS pedidos_valores_validos;
ALTER TABLE pedidos ADD CONSTRAINT pedidos_valores_validos CHECK (total >= 0 AND metodo_pago IN ('Efectivo', 'SINPE Móvil', 'Tarjeta', 'Transferencia') AND estado IN ('Pendiente', 'Aceptado', 'En preparación', 'En entrega', 'Entregado', 'Rechazado', 'Cancelado'));
ALTER TABLE detalle_pedidos DROP CONSTRAINT IF EXISTS detalle_pedidos_valores_validos;
ALTER TABLE detalle_pedidos ADD CONSTRAINT detalle_pedidos_valores_validos CHECK (cantidad > 0 AND precio_unitario >= 0 AND subtotal >= 0);
ALTER TABLE desechos DROP CONSTRAINT IF EXISTS desechos_valores_validos;
ALTER TABLE desechos ADD CONSTRAINT desechos_valores_validos CHECK (cantidad > 0 AND precio_compra >= 0);
